<?php
require_once __DIR__.'/db.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/audit.php';requireAdmin();$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');if($id&&in_array($status,['active','inactive'],true)){$s=$conn->prepare("UPDATE users SET status=? WHERE id=? AND role <> 'admin'");$s->bind_param('si',$status,$id);$s->execute();if($s->affected_rows){logAudit($conn,(int)$_SESSION['user_id'],'USER_STATUS_CHANGED','user',(string)$id,'Status changed to '.$status);$notice='User status updated.';}else $notice='No change made; admin accounts cannot be disabled here.';}else $notice='Invalid status request.';}
$rows=$conn->query('SELECT id,full_name,email,role,status,created_at FROM users ORDER BY id DESC')->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>User management</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="standalone"><a href="dashboard.php">← Dashboard</a><h1>User management</h1><p class="muted">Activate or deactivate non-admin accounts. Every change is audited.</p><?php if($notice):?><div class="alert success"><?=e($notice)?></div><?php endif;?><section class="panel"><div class="user-table-wrap"><table><thead><tr><th>USER</th><th>ROLE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><?=e($u['full_name'])?><small class="table-sub"><?=e($u['email'])?></small></td><td><?=e($u['role'])?></td><td><?=e($u['status'])?></td><td><?php if($u['role']!=='admin'):?><form method="post" onsubmit="return confirm('Change user status?')"><input type="hidden" name="id" value="<?=$u['id']?>"><input type="hidden" name="status" value="<?=$u['status']==='active'?'inactive':'active'?>"><button class="btn primary"><?=$u['status']==='active'?'Deactivate':'Activate'?></button></form><?php else:?>Protected<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
